import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import {
  expectRecordTitle,
  recordIdFromView,
  relatedListRecord,
  showRelatedList,
  waitForSpinners,
} from '../../support/lightning.js';

test.describe('SF-219 Contact appears in related list after creation', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-013 Contact appears in related list after creation',
    { tag: ['@ui', '@P3', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data }) => {
      meta({
        priority: 'P3',
        severity: 'trivial',
        feature: 'Contact',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-013',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const contactFirstName = data.unique('contact-first-name');
      const contactLastName = data.unique('contact-last-name');
      const contactEmailEmail = data.unique('contact-email', 'email');
      const viewed: Record<string, string> = {};
      await data.create('account-contact', ['Account', 'Contact']);
      await test.step('1. Navigate to Account, create and save new Contact', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC7): The Contact record page opens and shows the entered Last Name.
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await newContactDialog.firstName.fill(contactFirstName);
        await newContactDialog.lastName.fill(contactLastName);
        await newContactDialog.email.fill(contactEmailEmail);
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await data.adopt('Contact', 'Contact', 'LastName', contactLastName);
        viewed['Contact'] = await recordIdFromView(page, 'Contact');
        await expectRecordTitle(page, contactLastName);
      });
      await test.step('2. Return to Account record page and verify Contact in related list', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC7): The new Contact appears in the Contacts related list.
        await accountRecordPage.open(data.id('Account'));
        await expect(relatedListRecord(accountRecordPage.contactsRelatedList, contactLastName)).toBeVisible();
      });
    },
  );
});
